window.WeeklyReport=(()=>{
 const palette=['#20af83','#f6ad25','#f45b6b','#9db2cc','#3388ef'];
 function week(date){const day=Planning.day(date),dow=new Date(day*86400000).getUTCDay();return Planning.iso(day-(dow+6)%7)}
 function model(data,reports,date){const start=week(date),end=Planning.iso(Planning.day(start)+6),live=ProjectPortfolio.model(data,date);
  const rows=live.rows.map(row=>({...row,report:(reports[row.project.id]||[]).filter(r=>r.date>=start&&r.date<=end).sort((a,b)=>b.date.localeCompare(a.date)||String(b.id).localeCompare(String(a.id)))[0]}));
  const trend=Array.from({length:7},(_,i)=>{const from=Planning.iso(Planning.day(start)-(6-i)*7),to=Planning.iso(Planning.day(from)+6);return {date:from,count:rows.filter(r=>(reports[r.project.id]||[]).some(x=>x.date>=from&&x.date<=to)).length}});
  return {start,end,live,rows,trend,milestones:data.milestones.filter(m=>m.date>end&&m.date<=Planning.iso(Planning.day(end)+14)&&m.status!=='Completed').sort((a,b)=>a.date.localeCompare(b.date))};
 }
 function donut(items,total,label){let n=0;const stops=items.filter(x=>x.count).map(x=>{const prev=n;n+=x.count/Math.max(1,total)*100;return `${x.color} ${prev}% ${n}%`});return `<div class="pf-donut-layout"><div class="pf-donut" style="background:conic-gradient(${stops.join(',')||'#e3ecf6 0% 100%'})"><span><b>${total}</b>${label}</span></div><div class="pf-chart-legend">${items.map(x=>`<div><i style="background:${x.color}"></i>${esc(x.status)}<b>${x.count}</b></div>`).join('')}</div></div>`}
 function render(data,reports,options){const {date,avatar,today,selected,query='',filter='All',errors=[]}=options,m=model(data,reports,selected),live=ProjectPortfolio.model(data,today),counts=Object.fromEntries(live.counts.map(c=>[c.status,c.count]));
  const rows=m.rows.filter(r=>(filter==='All'||(filter==='Missing'?!r.report:r.report?.status===filter))&&(r.project.name+' '+(data.members.find(x=>x.id===r.project.managerId)?.name||'')).toLowerCase().includes(query.toLowerCase()));
  const priorities=['Critical','High','Medium','Low','Unspecified'].map((status,i)=>({status,count:data.issues.filter(t=>(t.priority||'Unspecified')===status).length,color:['#ce334d','#f45b6b','#f6ad25','#3388ef','#9db2cc'][i]}));
  const reported=m.rows.filter(r=>r.report),max=Math.max(1,m.rows.length),points=m.trend.map((x,i)=>`${35+i*43},${145-x.count/max*110}`).join(' ');
  const reportLink=r=>`<button class="text-btn" data-weekly-edit="${esc(r.project.id)}">${r.report?'Edit report':'Add report'}</button>`;
  return `<div class="pf-heading"><div><h1>▣ Project Weekly Report</h1><p>${date(m.start)} – ${date(m.end)} · Achievements, risks and next steps.</p></div><div class="wr-week"><button class="secondary" data-wr-shift="-7" aria-label="Previous week">‹</button><input type="date" id="wr-date" aria-label="Report week" value="${m.start}"><button class="secondary" data-wr-shift="7" aria-label="Next week">›</button><button class="secondary" data-wr-current>Today</button></div></div>${errors.length?`<p role="alert" class="wr-warning">Reports could not be loaded for ${errors.map(esc).join(', ')}. <button class="text-btn" data-wr-reload>Retry</button></p>`:''}<p class="pf-window">Project metrics are current as of ${date(today)}. Weekly narratives use the latest dated report in the selected week; no historical progress is inferred.</p><div class="pf-layout"><div class="pf-main"><section class="pf-kpis">${[['▱','Total Projects',live.rows.length,'Current portfolio','blue'],['✓','On Track',counts['On Track'],'Current health','green'],['△','At Risk',counts['At Risk'],'Current health','orange'],['!','Overdue',counts.Overdue,'Current health','red'],['♧','Team Members',live.people.length,'Distinct contributors','purple']].map(([icon,label,value,note,color])=>`<article class="panel pf-kpi ${color}"><i>${icon}</i><div><span>${label}</span><strong>${value}</strong><small>${note}</small></div></article>`).join('')}</section><div class="pf-charts"><section class="panel"><h2>Project Status Overview</h2><p class="pf-caption">Current portfolio health</p>${donut(live.counts.map((x,i)=>({...x,color:palette[i]})),live.rows.length,'Projects')}</section><section class="panel"><h2>Weekly Reporting Trend</h2><p class="pf-caption">Projects with a saved report · last 7 weeks</p><svg class="wr-trend" viewBox="0 0 330 180" role="img" aria-label="Weekly report coverage: ${m.trend.map(x=>x.date+': '+x.count+' projects').join('; ')}">${[0,.5,1].map(v=>`<path d="M35 ${145-v*110}H300" stroke="#e2edf8"/><text x="8" y="${149-v*110}">${Math.round(max*v)}</text>`).join('')}<polyline points="${points}" fill="none" stroke="#20af83" stroke-width="3"/>${m.trend.map((x,i)=>`<circle cx="${35+i*43}" cy="${145-x.count/max*110}" r="4" fill="#20af83"/><text x="${35+i*43}" y="169" text-anchor="middle">${x.date.slice(5)}</text>`).join('')}</svg></section><section class="panel"><h2>Tasks by Priority</h2><p class="pf-caption">Current tasks across all projects</p>${donut(priorities,data.issues.length,'Tasks')}</section></div><section class="panel pf-projects"><div class="pf-table-heading"><h2>Project Weekly Report</h2><span>${reported.length} / ${m.rows.length} projects reported</span></div><div class="pf-table-controls"><div class="pf-filters">${['All','On track','At risk','Off track','Complete','Missing'].map(x=>`<button data-wr-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><input id="wr-search" aria-label="Search weekly reports" placeholder="Search projects or owners…" value="${esc(query)}"></div><div class="bug-table-wrap"><table class="pf-table wr-table"><thead><tr><th>Project / report date</th><th>Owner</th><th>Weekly status</th><th>Current progress</th><th>This Week</th><th>Next Week</th><th>Risks / Key Notes</th><th>Report</th></tr></thead><tbody>${rows.map(r=>{const owner=data.members.find(x=>x.id===r.project.managerId),p=r.report;return `<tr><td><button class="pf-project-link" data-project-dashboard="${esc(r.project.id)}">${esc(r.project.name)}</button><small>${p?date(p.date):errors.includes(r.project.name)?'Unavailable':'No report this week'}</small></td><td><div class="pf-owner">${avatar(owner)}${esc(owner?.name||'Unassigned')}</div></td><td>${esc(p?.status||'—')}</td><td><div class="pf-progress-cell"><div class="pf-phase-track"><i style="width:${r.progress}%"></i></div>${r.progress}%</div></td><td>${esc(p?.progress||'—')}</td><td>${esc(p?.nextSteps||'—')}</td><td>${esc([p?.risks,p?.issues].filter(Boolean).join('\n')||'—')}</td><td>${reportLink(r)}</td></tr>`}).join('')||'<tr><td colspan="8">No projects match these filters.</td></tr>'}</tbody></table></div><div class="wr-takeaways"><div><h3>Key Takeaways</h3><p>${reported.length} projects have a report for this week; ${m.rows.length-reported.length} have no loaded report.</p><p>${reported.filter(r=>['At risk','Off track'].includes(r.report.status)).length} submitted reports flag delivery risks.</p></div><div><h3>Next Week Focus</h3>${reported.filter(r=>r.report.nextSteps).map(r=>`<p><b>${esc(r.project.name)}:</b> ${esc(r.report.nextSteps)}</p>`).join('')||'<p>Add next steps to a project status report to include them here.</p>'}</div></div></section></div><div class="pf-right"><section class="panel"><button class="secondary" data-wr-export ${errors.length?'disabled':''}>↓ Export Report (CSV)</button><button class="text-btn" data-wr-reload>Refresh reports</button></section><section class="panel"><h2>This Week Highlights</h2>${reported.map(r=>`<article class="wr-highlight"><button class="pf-project-link" data-weekly-edit="${esc(r.project.id)}">${esc(r.project.name)} ›</button><p>${esc(r.report.progress)}</p></article>`).join('')||'<p class="pf-empty">No saved reports for this week. Use Add report in the table to write one.</p>'}</section><section class="panel"><h2>Upcoming Milestones</h2><p class="pf-caption">Two weeks after this report period</p><div class="pf-milestones">${m.milestones.map(x=>`<button data-milestone-edit="${esc(x.id)}"><time>${date(x.date)}</time><span><strong>${esc(x.name)}</strong><small>${esc(data.projects.find(p=>p.id===x.projectId)?.name||'')}</small></span></button>`).join('')||'<p class="pf-empty">No milestones scheduled.</p>'}</div></section><section class="panel"><h2>Quick Links</h2>${[['portfolio','Project Portfolio'],['teams','Teams & Members'],['calendar','Project Calendar']].map(([id,label])=>`<button class="wr-quick text-btn" data-wr-nav="${id}">${label} →</button>`).join('')}</section></div></div>`;
 }
 function csv(data,reports,date,today){const m=model(data,reports,date),lines=[['Week start','Week end','Metrics as of','Project','Owner','Report date','Weekly status','Current progress %','Achievements','Next steps','Risks','Issues']];for(const r of m.rows){const p=r.report;lines.push([m.start,m.end,today,r.project.name,data.members.find(x=>x.id===r.project.managerId)?.name||'',p?.date||'',p?.status||'',r.progress,p?.progress||'',p?.nextSteps||'',p?.risks||'',p?.issues||''])}return '\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n')}
 return {week,model,render,csv};
})();
